      where: { personnelName: userName },
      order: [['createdAt', 'DESC']] 
    });

    res.status(200).json({
      personnelName: userName,
      logs: logs
    });
  } catch (error) {
    console.error("Failed to fetch personnel logs by ID:", error);
    res.status(500).json({ error: "Could not retrieve activity logs." });
  }
});

