1	import React, { useRef, useState, useEffect } from 'react';
2	import { useNavigate, useSearchParams } from 'react-router-dom';
3	import axios from 'axios';
4	import '../css/Enrollment.css';
5	
6	const FaceEnrollment = () => {
7	  const videoRef = useRef(null);
8	  const canvasRef = useRef(null);
9	  const navigate = useNavigate();
10	  const [searchParams] = useSearchParams();
11	
12	  const [enrollmentMode, setEnrollmentMode] = useState('camera'); // 'camera' | 'upload'
13	  const [stage, setStage] = useState('front'); // 'front', 'left', 'right', 'ready'
14	  const [photos, setPhotos] = useState({ front: null, left: null, right: null });
15	  const [loading, setLoading] = useState(false);
16	  const [errorMessage, setErrorMessage] = useState(null);
17	
18	  const token = localStorage.getItem("accessToken");
19	  const userName = localStorage.getItem("userName");
20	  const targetUserId = searchParams.get("userId");
21	  const targetUserName = searchParams.get("name");
22	  const returnTo = searchParams.get("returnTo") || "/dashboard";
23	  const isReEnrollment = Boolean(targetUserId);
24	  const displayName = targetUserName || userName || "FlowGuard user";
25	
26	  const allUploaded = photos.front && photos.left && photos.right;
27	
28	  useEffect(() => {
29	    startCamera();
30	    return () => stopCamera();
31	  }, []);
32	
33	  const startCamera = async () => {
34	    try {
35	      const stream = await navigator.mediaDevices.getUserMedia({ 
36	        video: {
37	          width: { ideal: 640 },
38	          height: { ideal: 480 },
39	          frameRate: { ideal: 15, max: 20 },
40	          facingMode: "user"
41	        }
42	      });
43	      if (videoRef.current) {
44	        videoRef.current.srcObject = stream;
45	      }
46	    } catch (err) {
47	      console.error("Camera access denied", err);
48	      setErrorMessage("Camera access denied. Please enable permissions to continue.");
49	    }
50	  };
51	
52	  const stopCamera = () => {
53	    if (videoRef.current && videoRef.current.srcObject) {
54	      const tracks = videoRef.current.srcObject.getTracks();
55	      tracks.forEach(track => track.stop());
56	    }
57	  };
58	
59	  const capturePhoto = () => {
60	    const video = videoRef.current;
61	    const canvas = canvasRef.current;
62	    
63	    if (video && canvas) {
64	      const context = canvas.getContext('2d');
65	      const maxWidth = 640;
66	      const scale = Math.min(1, maxWidth / video.videoWidth);
67	      canvas.width = Math.round(video.videoWidth * scale);
68	      canvas.height = Math.round(video.videoHeight * scale);
69	      context.drawImage(video, 0, 0, canvas.width, canvas.height);
70	      
71	      const imageDataUrl = canvas.toDataURL('image/jpeg', 0.75);
72	      
73	      setPhotos(prev => ({ ...prev, [stage]: imageDataUrl }));
74	      
75	      if (stage === 'front') setStage('left');
76	      else if (stage === 'left') setStage('right');
77	      else {
78	        setStage('ready');
79	        stopCamera();
80	      }
81	    }
82	  };
83	
84	  const switchMode = (mode) => {
85	    if (mode === enrollmentMode) return;
86	    setEnrollmentMode(mode);
87	    setPhotos({ front: null, left: null, right: null });
88	    setErrorMessage(null);
89	    setStage('front');
90	    if (mode === 'camera') {
91	      startCamera();
92	    } else {
93	      stopCamera();
94	    }
95	  };
96	
97	  const handleFileUpload = (angle, file) => {
98	    if (!file) return;
99	    if (!file.type.startsWith('image/')) {
100	      setErrorMessage("Please upload an image file for facial enrollment.");
101	      return;
102	    }
103	
104	    const reader = new FileReader();
105	    reader.onload = (e) => {
106	      setPhotos(prev => ({ ...prev, [angle]: e.target.result }));
107	      setErrorMessage(null);
108	    };
109	    reader.readAsDataURL(file);
110	  };
111	
112	  const resetCapture = () => {
113	    setPhotos({ front: null, left: null, right: null });
114	    setErrorMessage(null);
115	    setStage('front');
116	    if (enrollmentMode === 'camera') startCamera();
117	  };
118	
119	  const submitEnrollment = async () => {
120	    setLoading(true);
121	    setErrorMessage(null); // Clear any previous errors
122	
123	    try {
124	      // 🛑 THE FIX: Change to relative path so it uses the Vite Proxy
125	      await axios.post('/user/enroll-face', {
126	        images: photos,
127	        targetUserId: targetUserId ? Number(targetUserId) : undefined
128	      }, {
129	        headers: { Authorization: `Bearer ${token}` }
130	      });
131	      
132	      // Navigate to dashboard on success
133	      navigate(returnTo, {
134	        state: {
135	          notice: isReEnrollment
136	            ? `Face ID re-enrolled for ${displayName}.`
137	            : "Biometric enrollment successful."
138	        }
139	      }); 
140	    } catch (error) {
141	      console.error("Enrollment failed:", error);
142	      
143	      // Extract specific error from backend if available
144	      const backendError = error.response?.data?.error || "Facial vectoring failed. Ensure face is clearly visible.";
145	      setErrorMessage(backendError);
146	    } finally {
147	      setLoading(false);
148	    }
149	  };
150	
151	  const getInstructions = () => {
152	    if (enrollmentMode === 'upload') {
153	      return allUploaded ? "All angles uploaded. Ready to submit." : "Upload a clear photo for each angle below.";
154	    }
155	    switch(stage) {
156	      case 'front': return "Look directly at the camera.";
157	      case 'left': return "Turn your head slightly to the left.";
158	      case 'right': return "Turn your head slightly to the right.";
159	      case 'ready': return "All angles captured successfully.";
160	      default: return "";
161	    }
162	  };
163	
164	  return (
165	    <div className="enrollment-layout">
166	      <div className="enrollment-card">
167	        <div className="enrollment-header">
168	          <span className="security-icon">🛡️</span>
169	          <h2>{isReEnrollment ? 'Re-enroll Face ID' : 'Mandatory Biometric Setup'}</h2>
170	          <p>
171	            {isReEnrollment
172	              ? `Updating biometric access for ${displayName}. Capture or upload 3 fresh angles.`
173	              : `Welcome, ${displayName}. We need 3 angles to build a robust factory access profile.`}
174	          </p>
175	        </div>
176	
177	        {/* --- MODE TOGGLE --- */}
178	        <div className="mode-toggle">
179	          <button className={`mode-btn ${enrollmentMode === 'camera' ? 'active' : ''}`} onClick={() => switchMode('camera')}>
180	            📷 Use Camera
181	          </button>
182	          <button className={`mode-btn ${enrollmentMode === 'upload' ? 'active' : ''}`} onClick={() => switchMode('upload')}>
183	            ⬆ Upload Photos
184	          </button>
185	        </div>
186	
187	        <div className="progress-tracker">
188	            <span className={`tracker-badge ${photos.front ? 'done' : enrollmentMode === 'camera' && stage === 'front' ? 'active' : ''}`}>Front</span>
189	            <span className="tracker-line"></span>
190	            <span className={`tracker-badge ${photos.left ? 'done' : enrollmentMode === 'camera' && stage === 'left' ? 'active' : ''}`}>Left</span>
191	            <span className="tracker-line"></span>
192	            <span className={`tracker-badge ${photos.right ? 'done' : enrollmentMode === 'camera' && stage === 'right' ? 'active' : ''}`}>Right</span>
193	        </div>
194	
195	        <div className="camera-container">
196	          <canvas ref={canvasRef} style={{ display: 'none' }} />
197	
198	          {enrollmentMode === 'camera' ? (
199	            stage === 'ready' ? (
200	              <div className="preview-grid">
201	                <img src={photos.front} alt="Front" className="preview-thumb" />
202	                <img src={photos.left} alt="Left" className="preview-thumb" />
203	                <img src={photos.right} alt="Right" className="preview-thumb" />
204	              </div>
205	            ) : (
206	              <div className="video-wrapper">
207	                <video ref={videoRef} autoPlay playsInline muted className="live-video" />
208	                <div className={`face-guide-overlay ${stage}`}></div>
209	              </div>
210	            )
211	          ) : (
212	            <div className="upload-grid">
213	              {['front', 'left', 'right'].map((angle) => (
214	                <label key={angle} className={`upload-zone ${photos[angle] ? 'uploaded' : ''}`}>
215	                  <input
216	                    type="file"
217	                    accept="image/*"
218	                    style={{ display: 'none' }}
219	                    onChange={(e) => handleFileUpload(angle, e.target.files[0])}
220	                  />
221	                  {photos[angle] ? (
222	                    <>
223	                      <img src={photos[angle]} alt={angle} className="upload-preview" />
224	                      <span className="upload-label done-label">✓ {angle.charAt(0).toUpperCase() + angle.slice(1)}</span>
225	                    </>
226	                  ) : (
227	                    <>
228	                      <span className="upload-icon">+</span>
229	                      <span className="upload-label">{angle.charAt(0).toUpperCase() + angle.slice(1)}</span>
230	                    </>
231	                  )}
