6	
7	const GateScanner = () => {
8	  const videoRef = useRef(null);
9	  const canvasRef = useRef(null);
10	  
11	  const [scanStatus, setScanStatus] = useState("SYSTEM_ACTIVE"); 
12	  const [displayMessage, setDisplayMessage] = useState("PLACE FACE IN VIEWPORT");
13	  const [faceBox, setFaceBox] = useState(null); 
14	  const [scanProgress, setScanProgress] = useState(0); 
15	  
16	  const scanStatusRef = useRef("SYSTEM_ACTIVE");
17	  const lockTimerRef = useRef(null);
18	  const progressIntervalRef = useRef(null);
19	  const candidateUserRef = useRef(null); 
20	  const isScanningRef = useRef(false);
21	
22	  const token = localStorage.getItem("accessToken");
23	  const ATTENDANCE_SCAN_URL = "/api/attendance/scan";
24	
25	  const changeScanState = (nextState, message) => {
26	    setScanStatus(nextState);
27	    scanStatusRef.current = nextState;
28	    if (message) setDisplayMessage(message);
29	  };
30	
31	  useEffect(() => {
32	    startGateCamera();
33	    const scanInterval = setInterval(() => performPerimeterScan(), 1200);
34	
35	    return () => {
36	      stopGateCamera();
37	      clearInterval(scanInterval);
38	      if (lockTimerRef.current) clearTimeout(lockTimerRef.current);
39	      if (progressIntervalRef.current) clearInterval(progressIntervalRef.current);
40	    };
41	  }, []);
42	
43	  const startGateCamera = async () => {
44	    try {
45	      const stream = await navigator.mediaDevices.getUserMedia({
46	        video: {
47	          width: { ideal: 640 },
48	          height: { ideal: 480 },
49	          frameRate: { ideal: 15, max: 20 },
50	          facingMode: "user"
51	        },
52	        audio: false
53	      });
54	      if (videoRef.current) {
55	        videoRef.current.srcObject = stream;
56	        videoRef.current.onloadedmetadata = () => {
57	          videoRef.current.play().catch(() => changeScanState("HARDWARE_ERR", "CAMERA STREAM PAUSED"));
58	        };
59	      }
60	      changeScanState("SYSTEM_ACTIVE", "GATE TURNSTILE ONLINE // AWAITING TARGET");
61	    } catch (err) { 
62	      changeScanState("HARDWARE_ERR", "HARDWARE FAILURE: CAMERA NOT DETECTED"); 
63	    }
64	  };
65	
66	  const stopGateCamera = () => {
67	    if (videoRef.current?.srcObject) {
68	      videoRef.current.srcObject.getTracks().forEach(track => track.stop());
69	    }
70	  };
71	
72	  const processAttendanceTransaction = async (verifiedName) => {
73	    changeScanState("SECURE_MATCH", "IDENTITY VERIFIED // PROCESSING TIMECARD");
74	    setScanProgress(100);
75	
76	    try {
77	      // 🎯 Hit the Node.js automatic clock-in/out controller
78	      const res = await axios.post(ATTENDANCE_SCAN_URL, { name: verifiedName }, {
79	        headers: { Authorization: `Bearer ${token}` }
80	      });
81	
82	      if (res.data && res.data.action) {
83	        // Render the exact system response action directly onto the kiosk screen
84	        const actionMessage = res.data.action.replace(/_/g, " ");
85	        setDisplayMessage(`🔓 ${verifiedName}: ${actionMessage}`);
86	      }
87	    } catch (err) {
88	      console.error("Attendance Sync Failed:", err);
89	      setDisplayMessage("🚨 GATE TRANSACTION ROUTING FAULT");
90	    }
91	
92	    setTimeout(() => { resetTurnstileKiosk(); }, 4000);
93	  };
94	
95	  const performPerimeterScan = async () => {
96	    if (isScanningRef.current) return;
97	
98	    const video = videoRef.current;
99	    const canvas = canvasRef.current;
100	    
101	    if (!video || !canvas || video.videoWidth === 0) return;
102	    if (scanStatusRef.current === "SECURE_MATCH" || scanStatusRef.current === "UNKNOWN_QUERY") return;
103	
104	    isScanningRef.current = true;
105	    const context = canvas.getContext('2d');
106	    const maxWidth = 420;
107	    const scale = Math.min(1, maxWidth / video.videoWidth);
108	    canvas.width = Math.round(video.videoWidth * scale);
109	    canvas.height = Math.round(video.videoHeight * scale);
110	    context.drawImage(video, 0, 0, canvas.width, canvas.height);
111	    const imageBase64 = canvas.toDataURL('image/jpeg', 0.3);
112	
113	    try {
114	      const res = await axios.post('/ai/user/recognize', { image: imageBase64 }, {
115	        headers: { Authorization: `Bearer ${token}` }
116	      });
117	
118	      if (scanStatusRef.current === "SECURE_MATCH" || scanStatusRef.current === "UNKNOWN_QUERY") return;
119	
120	      if (res.data && res.data.box && res.data.box.length >= 4) {
121	        let rawX, rawY, boxWidth, boxHeight;
122	        const [v1, v2, v3, v4] = res.data.box;
123	        if (v2 > v4 && v3 > v1) { rawY = v1; rawX = v4; boxWidth = v2 - v4; boxHeight = v3 - v1; } 
124	        else { rawX = v1; rawY = v2; boxWidth = v3; boxHeight = v4; }
125	        
126	        const faceProximityPercentage = (boxWidth / canvas.width) * 100;
127	        const livenessRatio = res.data.liveness_ratio || 0.5;
128	
129	        const targetBox = {
130	          left: `${(rawX / canvas.width) * 100}%`, top: `${(rawY / canvas.height) * 100}%`,
131	          width: `${(boxWidth / canvas.width) * 100}%`, height: `${(boxHeight / canvas.height) * 100}%`
132	        };
133	
134	        if (faceProximityPercentage < 8 && scanStatusRef.current !== "LIVENESS_CHECK") {
135	          changeScanState("PRESENCE_DETECTED", "TARGET DETECTED // MOVE CLOSER");
136	          setFaceBox(null); 
137	          return;
138	        }
139	
140	        // 🎯 LIVENESS CHECK: Wait for head swing rotation
141	        if (scanStatusRef.current === "LIVENESS_CHECK") {
142	          setFaceBox(targetBox);
143	          if (livenessRatio < 0.35 || livenessRatio > 0.65) {
144	            await processAttendanceTransaction(candidateUserRef.current);
145	          }
146	          return;
147	        }
148	
149	        // TARGET LOCKING SEQUENCE
150	        if (scanStatusRef.current === "SYSTEM_ACTIVE" || scanStatusRef.current === "PRESENCE_DETECTED") {
151	          changeScanState("TARGET_LOCKING", "LOCKING BIOMETRIC VECTORS...");
152	          setFaceBox(targetBox);
153	          setScanProgress(12);
154	
155	          let progress = 12;
156	          progressIntervalRef.current = setInterval(() => {
157	            progress += Math.floor(Math.random() * 14) + 4;
158	            if (progress >= 96) { setScanProgress(96); clearInterval(progressIntervalRef.current); } 
159	            else { setScanProgress(progress); }
160	          }, 120);
161	
162	          lockTimerRef.current = setTimeout(() => {
163	            clearInterval(progressIntervalRef.current);
164	
165	            if (res.data.user && res.data.user.name !== "UNAUTHORIZED") {
166	              candidateUserRef.current = res.data.user.name;
167	              changeScanState("LIVENESS_CHECK", "VERIFYING LIVENESS: TURN HEAD SLIGHTLY");
168	            } else {
169	              changeScanState("UNKNOWN_QUERY", "🚨 PERIMETER BREACH: ACCESS DENIED");
170	              setScanProgress(0);
171	              setTimeout(() => { resetTurnstileKiosk(); }, 3500);
172	            }
173	          }, 1800);
174	        } else if (scanStatusRef.current === "TARGET_LOCKING") {
175	          setFaceBox(targetBox);
176	        }
177	      } else {
178	        if (scanStatusRef.current !== "LIVENESS_CHECK" && scanStatusRef.current !== "TARGET_LOCKING") {
179	          resetTurnstileKiosk();
180	        }
181	      }
182	    } catch (err) {
183	      console.error("Gate AI Link Fault:", err);
184	    } finally {
185	      isScanningRef.current = false;
186	    }
187	  };
188	
189	  const resetTurnstileKiosk = () => {
190	    setFaceBox(null);
191	    setScanProgress(0);
192	    candidateUserRef.current = null;
193	    changeScanState("SYSTEM_ACTIVE", "GATE TURNSTILE ONLINE // AWAITING TARGET");
194	  };
195	
196	  return (
197	    <div className="dashboard-layout">
