    const Booking = sequelize.define("Booking", {
        // booking_ref doubles as the booking code AND the QR token shown on the driver pass.
        booking_ref: {
            type: DataTypes.STRING(50),
            allowNull: false,
            unique: true
        },
        // --- Ownership (for tenant isolation) ---
        tenant_name: {
            type: DataTypes.STRING(255),
            allowNull: true
        },
