            type: DataTypes.INTEGER,
            allowNull: true // users.id of the tenant who created it (set on tenant-created bookings)
        },
        // --- Delivery details ---
        driver_name: {
            type: DataTypes.STRING(255),
            allowNull: true
        },
        transport_company: {
            type: DataTypes.STRING(255),
            allowNull: false
        },
        license_plate: {
            type: DataTypes.STRING(20),
            allowNull: false
        },
        driver_phone: {
            type: DataTypes.STRING(20),
            allowNull: false
        },
        loading_bay: {
            type: DataTypes.STRING(50),
            allowNull: false
        },
        // --- Scheduling ---
        slot_start: {
            type: DataTypes.DATE,
            allowNull: true
        },
        slot_end: {
            type: DataTypes.DATE,
            allowNull: true
        },
        // Pending | Confirmed | Arrived | Completed | Cancelled
