file.content:
/* --- Settings Grid Layout --- */
.settings-grid {
  display: flex;
  flex-direction: column;
  gap: 24px;
  width: 100%; /* Stretch to full width */
  /* animation: slideUpFade 0.5s ease-out; */
  /* Removed the 900px max-width from here */
}

/* --- Centered Header -> Full Width --- */
.settings-header {
  width: 100%;
  margin-bottom: 30px;
  /* Removed margin: 0 auto */
}

/* --- Settings Cards --- */
.settings-card {
  background-color: #1e293b;
  border: 1px solid #334155;
  border-radius: 12px;
  overflow: hidden;
  width: 100%; 
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
}

.card-header {
  padding: 24px 30px;
  border-bottom: 1px solid #334155;
  background-color: rgba(15, 23, 42, 0.3);
}

/* --- Individual Setting Rows --- */
.setting-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24px 30px; 
  border-bottom: 1px solid #334155;
}

.setting-row:last-child {
  border-bottom: none;
}

.setting-info {
  flex: 1;
  max-width: 700px; /* Keeps text readable even when the card stretches wide */
}

.setting-info h4 {
  margin: 0 0 5px 0;
  color: #e2e8f0;
  font-size: 1.05rem;
  font-weight: 500;
}

/* --- UI Controls --- */
.setting-control {
  display: flex;
  justify-content: flex-end;
  min-width: 200px; /* Ensures controls have breathing room */
}

/* Toggle Switch, Slider, and Select styles remain the same... */

/* --- Danger Zone --- */
.danger-zone { border-color: rgba(239, 68, 68, 0.3); }
.text-red { color: #f87171 !important; }

.danger-btn {
  background-color: transparent;
  color: #ef4444;
  border: 1px solid #ef4444;
  padding: 8px 16px;
  border-radius: 6px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
}

/* --- Bottom Action Area --- */
.settings-actions {
    display: flex;
    justify-content: flex-end;
    padding: 20px 0;
    margin-bottom: 50px; 
}

/* --- Mobile Responsiveness --- */
@media (max-width: 768px) {
  .setting-row {
    flex-direction: column;
    align-items: flex-start;
    gap: 15px;
  }

  .setting-control {
    width: 100%;
    justify-content: flex-end; 
  }
}

