/* --- TENANT LOGISTICS (DESKTOP GRID) --- */
.booking-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr;
  gap: 30px;
}

.booking-card {
  background: #1e2539;
  border-radius: 16px;
  border: 1px solid #2d364f;
  padding: 30px;
}

.booking-card h2 {
  margin: 0 0 25px 0;
  font-size: 1.4rem;
  color: #f8fafc;
}

/* --- DARK FORMS --- */
.dark-form .form-group {
  margin-bottom: 20px;
  display: flex;
  flex-direction: column;
}

.dark-form label {
  color: #94a3b8;
  font-size: 0.85rem;
  margin-bottom: 8px;
  font-weight: 500;
}

.dark-form input, .dark-form select {
  background: #0b0f1a;
  border: 1px solid #2d364f;
  color: #f8fafc;
  padding: 14px;
  border-radius: 8px;
  font-size: 1rem;
  transition: 0.2s;
  outline: none;
}

.dark-form input:focus, .dark-form select:focus {
