  padding: 16px;
  background: #3b82f6;
  color: white;
  border: none;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  margin-top: 10px;
  transition: 0.2s;
}

.submit-booking-btn:hover { background: #2563eb; }

/* --- ACTIVE BOOKINGS LIST --- */
.arrival-list {
  display: flex;
  flex-direction: column;
  gap: 15px;
}

.arrival-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 15px;
  background: #0b0f1a;
  border-radius: 10px;
