/* Reusable show/hide password field (dark theme, scoped). */
.password-field {
  position: relative;
  width: 100%;
}

/* Leave room for the toggle button so typed text never overlaps it. */
.password-field input {
  padding-right: 42px !important;
  box-sizing: border-box;
}

.password-toggle {
  position: absolute;
  right: 8px;
  top: 50%;
  transform: translateY(-50%);
  background: transparent;
  border: none;
  cursor: pointer;
  font-size: 1rem;
  line-height: 1;
  padding: 4px 6px;
  border-radius: 6px;
  color: #94a3b8;
  opacity: 0.85;
  transition: opacity 0.2s, background 0.2s;
}

.password-toggle:hover {
  opacity: 1;
  background: rgba(148, 163, 184, 0.12);
}

.password-toggle:focus-visible {
  outline: 2px solid #3b82f6;
  outline-offset: 1px;
}

