/* --- TENANT LOGISTICS (DESKTOP GRID) --- */
.booking-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr;
  gap: 30px;
}

.booking-card {
  background: #1e2539;
  border-radius: 16px;
  border: 1px solid #2d364f;
  padding: 30px;
}

.booking-card h2 {
  margin: 0 0 25px 0;
  font-size: 1.4rem;
  color: #f8fafc;
}

/* --- DARK FORMS --- */
.dark-form .form-group {
  margin-bottom: 20px;
  display: flex;
  flex-direction: column;
}

.dark-form label {
  color: #94a3b8;
  font-size: 0.85rem;
  margin-bottom: 8px;
  font-weight: 500;
}

.dark-form input, .dark-form select {
  background: #0b0f1a;
  border: 1px solid #2d364f;
  color: #f8fafc;
  padding: 14px;
  border-radius: 8px;
  font-size: 1rem;
  transition: 0.2s;
  outline: none;
}

.dark-form input:focus, .dark-form select:focus {
  border-color: #3b82f6;
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.1);
}

.submit-booking-btn {
  width: 100%;
  padding: 16px;
  background: #3b82f6;
  color: white;
  border: none;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  margin-top: 10px;
  transition: 0.2s;
}

.submit-booking-btn:hover { background: #2563eb; }

/* --- ACTIVE BOOKINGS LIST --- */
.arrival-list {
  display: flex;
  flex-direction: column;
  gap: 15px;
}

.arrival-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 15px;
  background: #0b0f1a;
  border-radius: 10px;
  border: 1px solid #2d364f;
}

.arrival-info {
  display: flex;
  flex-direction: column;
}

.arrival-info strong { color: #f8fafc; font-size: 1rem; }
.arrival-info span { color: #707a91; font-size: 0.8rem; margin-top: 4px; }

.time-badge {
  background: rgba(52, 211, 153, 0.15);
  color: #34d399;
  padding: 6px 12px;
  border-radius: 20px;
  font-size: 0.85rem;
  font-weight: 600;
}
.time-badge.warning {
  background: rgba(245, 158, 11, 0.15);
  color: #f59e0b;
}

/* =========================================
   DRIVER PORTAL (MOBILE-FIRST)
   ========================================= */
.driver-mobile-layout {
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  background-color: #0b0f1a;
  padding: 20px;
  font-family: 'Inter', sans-serif;
}

.driver-mobile-container {
  width: 100%;
  max-width: 450px; 
  background: #1e2539;
  border-radius: 24px;
  border: 1px solid #2d364f;
  padding: 30px;
  box-shadow: 0 20px 40px rgba(0,0,0,0.4);
}

.mobile-header {
  text-align: center;
  margin-bottom: 30px;
}

.mobile-header h2 { margin: 0; font-size: 1.8rem; }
.mobile-header p { color: #94a3b8; margin: 5px 0 0 0; font-size: 0.9rem; }

.instruction-box h3 { color: #f8fafc; margin: 0 0 5px 0; font-size: 1.2rem; }
.instruction-box p { color: #707a91; font-size: 0.9rem; margin: 0 0 20px 0; line-height: 1.4; }

.time-slot-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 15px;
  margin-bottom: 30px;
}

.time-slot-btn {
  background: #0b0f1a;
  border: 1px solid #2d364f;
  color: #f8fafc;
  padding: 15px;
  border-radius: 12px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
}

.time-slot-btn:hover { border-color: #60a5fa; }

.time-slot-btn.selected {
  background: #3b82f6;
  border-color: #3b82f6;
  color: white;
  box-shadow: 0 4px 15px rgba(59, 130, 246, 0.4);
}

.confirm-slot-btn {
  width: 100%;
  padding: 18px;
  background: #34d399;
  color: #0b0f1a;
  border: none;
  border-radius: 12px;
  font-size: 1.1rem;
  font-weight: 700;
  cursor: pointer;
  transition: 0.2s;
}

.confirm-slot-btn:disabled {
  background: #2d364f;
  color: #707a91;
  cursor: not-allowed;
}

/* =========================================
   LOGISTICS RESPONSIVE BEHAVIOUR
   ========================================= */

/* Allow grid children to shrink instead of overflowing on smaller laptops. */
.booking-grid > .booking-card { min-width: 0; }

/* Bookings table scrolls horizontally (scoped to logistics) rather than being
   clipped by the global `.table-container { overflow: hidden }`. */
.active-bookings .table-container { overflow-x: auto; }
.active-bookings .management-table { min-width: 820px; } /* 8 columns; full-width card fits a laptop without scroll */

/* Tablet / smaller laptop: stack the form above the bookings table. */
@media (max-width: 1024px) {
  .booking-grid { grid-template-columns: 1fr; }
}

/* Phones: tighter padding. The global table switches to a labelled card layout,
   so drop the min-width to avoid an unnecessary horizontal scrollbar. */
@media (max-width: 768px) {
  .booking-grid { grid-template-columns: 1fr; gap: 20px; }
  .booking-card { padding: 20px; }
  .active-bookings .management-table { min-width: 0; }
}

/* =========================================
   LOGISTICS DASHBOARD (header actions, stats, filters, modal)
   ========================================= */
.header-actions { display: flex; gap: 10px; align-items: center; }

/* Refresh button: match the + New Booking metrics (height/padding/radius/weight)
   with a secondary dark style so it aligns and doesn't look weaker. */
.header-actions .edit-btn {
  margin: 0;
  padding: 10px 18px;
  font-size: 0.9rem;
  font-weight: 600;
  border-radius: 8px;
  background: #1e293b;
  border: 1px solid #334155;
  color: #cbd5e1;
}
.header-actions .edit-btn:hover { background: #334155; color: #fff; }

.new-booking-btn {
  background: #3b82f6;
  color: #fff;
  border: none;
  border-radius: 8px;
  padding: 10px 18px;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, box-shadow 0.2s;
}
.new-booking-btn:hover { background: #2563eb; }
.new-booking-btn:focus-visible { outline: none; box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.4); }

/* Summary cards */
.logistics-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-bottom: 20px;
}
.logistics-stat-card {
  background: #1e2539;
  border: 1px solid #2d364f;
  border-radius: 12px;
  padding: 18px 20px;
}
.logistics-stat-card .stat-value { font-size: 1.8rem; font-weight: 700; color: #f8fafc; }
.logistics-stat-card .stat-label { color: #94a3b8; font-size: 0.8rem; margin-top: 4px; }

/* Filters toolbar */
.logistics-toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  align-items: center;
  margin-bottom: 18px;
}
.logistics-search { flex: 1; min-width: 220px; }
.logistics-search input,
.logistics-filter {
  background: #0b0f1a;
  border: 1px solid #2d364f;
  color: #f8fafc;
  padding: 10px 12px;
  border-radius: 8px;
  font-size: 0.9rem;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
}
.logistics-search input { width: 100%; }
.logistics-search input:focus,
.logistics-filter:focus { border-color: #3b82f6; box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15); }
.logistics-filter option { background: #0b0f1a; color: #f8fafc; }

/* Dark-theme native date/time pickers — booking modal slots + logistics date filter.
   Scoped to .dark-form / .logistics-date so auth pages (Login/Register) are unaffected. */
.dark-form input[type="datetime-local"],
.dark-form input[type="date"],
.logistics-date {
  color-scheme: dark;
}
.dark-form input[type="datetime-local"]::-webkit-calendar-picker-indicator,
.dark-form input[type="date"]::-webkit-calendar-picker-indicator,
.logistics-date::-webkit-calendar-picker-indicator {
  filter: invert(1);
  opacity: 0.85;
  cursor: pointer;
}

/* Create-booking modal (reuses global .modal-overlay / .modal-content) */
.booking-modal {
  text-align: left;
  width: 92%;
  max-width: 520px;
  max-height: 88vh;
  overflow-y: auto;
}
.booking-modal-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 18px;
}
.booking-modal-head h2 { margin: 0; font-size: 1.3rem; color: #f8fafc; }
.modal-x {
  background: transparent;
  border: none;
  color: #94a3b8;
  font-size: 1.1rem;
  cursor: pointer;
  padding: 4px 8px;
  border-radius: 6px;
}
.modal-x:hover { color: #f8fafc; background: #334155; }
.booking-modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 12px;
  margin-top: 8px;
}
.booking-modal-actions .submit-booking-btn { width: auto; margin-top: 0; }

@media (max-width: 1024px) {
  .logistics-stats { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 768px) {
  .logistics-stats { grid-template-columns: 1fr; }
  .header-actions { width: 100%; }
  .header-actions .edit-btn,
  .header-actions .new-booking-btn { flex: 1; }
}

