1	const express = require('express');
2	const router = express.Router();
3	const crypto = require('crypto');
4	const { Op } = require('sequelize');
5	const { Booking } = require('../models');
6	const { verifyToken, requireRole } = require('../middlewares/auth');
7	const whatsapp = require('../services/whatsappService');
8	
9	const STATUSES = ['Pending', 'Confirmed', 'Arrived', 'Completed', 'Cancelled'];
10	
11	function genRef() {
12	    return `FG-${crypto.randomBytes(3).toString('hex').toUpperCase()}`;
13	}
14	
15	// ---------------------------------------------------------------------------
16	// CREATE — FM or Tenant create a loading-bay booking request.  (400 on bad input)
17	// ---------------------------------------------------------------------------
18	router.post('/create', verifyToken, requireRole('FM', 'Tenant'), async (req, res) => {
19	    try {
20	        const {
21	            transport_company, license_plate, driver_phone, loading_bay,
22	            driver_name, slot_start, slot_end, notes, tenant_name
23	        } = req.body;
24	
25	        const missing = ['transport_company', 'license_plate', 'driver_phone', 'loading_bay']
26	            .filter(f => !req.body[f] || !String(req.body[f]).trim());
27	        if (missing.length) {
28	            return res.status(400).json({ error: `Missing required field(s): ${missing.join(', ')}.` });
29	        }
30	        if (!/^[+\d][\d\s-]{6,}$/.test(String(driver_phone))) {
31	            return res.status(400).json({ error: 'driver_phone is not a valid phone number.' });
32	        }
33	
34	        // Optional slot-conflict guard (409) when a time window is supplied.
35	        if (slot_start && slot_end) {
36	            if (new Date(slot_end) <= new Date(slot_start)) {
37	                return res.status(400).json({ error: 'slot_end must be after slot_start.' });
38	            }
39	            const clash = await Booking.findOne({
40	                where: {
41	                    loading_bay,
42	                    status: { [Op.ne]: 'Cancelled' },
43	                    slot_start: { [Op.lt]: new Date(slot_end) },
44	                    slot_end: { [Op.gt]: new Date(slot_start) }
45	                }
46	            });
47	            if (clash) {
48	                return res.status(409).json({ error: `${loading_bay} is already booked for that time window.` });
49	            }
50	        }
51	
52	        const booking = await Booking.create({
53	            booking_ref: genRef(),
54	            transport_company,
55	            license_plate,
56	            driver_phone,
57	            loading_bay,
58	            driver_name: driver_name || null,
59	            slot_start: slot_start || null,
60	            slot_end: slot_end || null,
61	            notes: notes || null,
