router.patch('/:id/cancel', verifyToken, async (req, res) => {
    try {
        const booking = await Booking.findByPk(req.params.id);
        if (!booking) return res.status(404).json({ error: 'Booking not found.' });

        const isFM = req.user.role === 'FM';
