                </div>

                <div className="info-grid">
                    <div className="info-item">
                        <label>Driver</label>
                        <p>{booking.driver_name || "—"}</p>
                    </div>
                    <div className="info-item">
                        <label>License Plate</label>
                        <p>{booking.license_plate}</p>
