                    <div className="info-item">
                        <label>Loading Bay</label>
                        <p className="bay-highlight">{booking.loading_bay}</p>
                    </div>
                    <div className="info-item">
                        <label>Transport Co.</label>
                        <p>{booking.transport_company}</p>
